    @Test
    public void testSetClip_positiveCoordinates() {
        CohenSutherlandClipping clipper = new CohenSutherlandClipping();
        // Define a clip window with positive coordinates and dimensions
        Rectangle2D clipWindow = new Rectangle2D.Double(10.0, 20.0, 30.0, 40.0); // x=10, y=20, width=30, height=40
        // Expected internal state after setClip: xMin=10, yMin=20, xMax=40 (10+30), yMax=60 (20+40)

        // Call the focal method
        clipper.setClip(clipWindow);

        // Verify the effect of setClip through the public 'clip' method,
        // as private fields (xMin, yMin, xMax, yMax) cannot be directly accessed.

        // Test 1: Line completely inside the expected clipping window
        Line2D.Float lineInside = new Line2D.Float(15.0f, 25.0f, 35.0f, 55.0f);
        assertTrue("Line completely inside the clip window should remain visible", clipper.clip(lineInside));

        // Test 2: Line completely outside (left of xMin)
        Line2D.Float lineOutsideLeft = new Line2D.Float(0.0f, 30.0f, 5.0f, 40.0f);
        assertFalse("Line completely outside (left) should be clipped away", clipper.clip(lineOutsideLeft));

        // Test 3: Line completely outside (right of xMax)
        Line2D.Float lineOutsideRight = new Line2D.Float(45.0f, 30.0f, 50.0f, 40.0f);
        assertFalse("Line completely outside (right) should be clipped away", clipper.clip(lineOutsideRight));

        // Test 4: Line completely outside (above yMin)
        Line2D.Float lineOutsideAbove = new Line2D.Float(20.0f, 0.0f, 30.0f, 15.0f);
        assertFalse("Line completely outside (above) should be clipped away", clipper.clip(lineOutsideAbove));

        // Test 5: Line completely outside (below yMax)
        Line2D.Float lineOutsideBelow = new Line2D.Float(20.0f, 65.0f, 30.0f, 70.0f);
        assertFalse("Line completely outside (below) should be clipped away", clipper.clip(lineOutsideBelow));

        // Test 6: Line partially intersecting (crossing xMin boundary)
        Line2D.Float linePartialLeft = new Line2D.Float(5.0f, 30.0f, 15.0f, 30.0f);
        assertTrue("Line partially intersecting (left) should remain visible", clipper.clip(linePartialLeft));

        // Test 7: Line partially intersecting (crossing yMin boundary)
        Line2D.Float linePartialTop = new Line2D.Float(20.0f, 15.0f, 20.0f, 25.0f);
        assertTrue("Line partially intersecting (top) should remain visible", clipper.clip(linePartialTop));
    }
